// Turns everything the three folder reads found into work items, once.
// Ledger and attempt counts live in workflow static data, which n8n persists for
// production (trigger) executions. A file is sent at most MAX_ATTEMPTS times; after
// that it is reported once as rejected and skipped until renamed.
// Static data is only saved when a run ends, so overlapping runs cannot see each
// other's attempts. A long Whisper call (up to 30 min) would be re-sent by every
// 2-minute tick, so voice is serialised through the inbox_lock data table: one
// voice file per run, and none while another run's lock is younger than LOCK_MINUTES.
const MAX_ATTEMPTS = 3;
const PER_RUN = 20;
const VOICE_PER_RUN = 1;
const LOCK_MINUTES = 35;
const ROOT = '/home/node/.n8n-files/inbox';
const sd = $getWorkflowStaticData('global');
sd.processed = sd.processed || {};
sd.attempts = sd.attempts || {};
sd.rejected = sd.rejected || {};

const notes = $('List voice notes').first().json;
// Only the old voice workflow's notes, named exactly after the file, are matched here; it
// kept no ledger. Dated notes are covered by the ledger. Matching them by title would also
// swallow every later recording of a recurring title ("standup", a place name).
const voiceNotes = new Set(
  (Array.isArray(notes.files) ? notes.files : []).map((f) => f.replace(/\.md$/, '')),
);
const noteBase = (name) => name.replace(/\.[^.]+$/, '').replace(/[\\/:*?"<>|]/g, '-');

const found = [];
const collect = (nodeName, target) => {
  for (const item of $(nodeName).all()) {
    const bin = item.binary && item.binary.data;
    if (!bin || !bin.fileName) continue;
    const name = bin.fileName;
    if (name.startsWith('.') || name.endsWith('.icloud')) continue;
    const dir = bin.directory || '';
    let notebook = null;
    if (target === 'bujo') {
      const rel = dir.startsWith(ROOT + '/bujo') ? dir.slice((ROOT + '/bujo').length).replace(/^\/+/, '') : '';
      notebook = rel.split('/')[0] || 'Unsorted';
    }
    const key = `${target}:${dir}/${name}:${bin.fileSize || ''}`;
    found.push({ key, target, notebook, name, binary: item.binary });
  }
};
collect('Read bujo', 'bujo');
collect('Read voice', 'voice');
collect('Read legacy voice', 'voice');

const lock = $('Read lock').all().map((i) => i.json).find((r) => r && r.name === 'shared-inbox');
const lockAge = lock && lock.started_at ? Date.now() - new Date(lock.started_at).getTime() : Infinity;
const voiceLocked = lockAge < LOCK_MINUTES * 60 * 1000;
let voiceTaken = 0;

const out = [];
for (const f of found) {
  if (sd.processed[f.key] || sd.rejected[f.key]) continue;
  if (f.target === 'voice' && voiceNotes.has(noteBase(f.name))) {
    sd.processed[f.key] = new Date().toISOString();
    continue;
  }
  if (f.target === 'voice' && (voiceLocked || voiceTaken >= VOICE_PER_RUN)) continue;
  const tries = (sd.attempts[f.key] || 0) + 1;
  if (tries > MAX_ATTEMPTS) {
    sd.rejected[f.key] = new Date().toISOString();
    delete sd.attempts[f.key];
    out.push({ json: { target: 'rejected', key: f.key, detail: `${f.target}: ${f.name} failed ${MAX_ATTEMPTS} times` } });
    continue;
  }
  if (out.filter((o) => o.json.target !== 'rejected').length >= PER_RUN) continue;
  sd.attempts[f.key] = tries;
  if (f.target === 'voice') voiceTaken++;
  out.push({ json: { key: f.key, target: f.target, notebook: f.notebook, src: f.name, noteName: noteBase(f.name), source: 'icloud' }, binary: f.binary });
}

const keys = Object.keys(sd.processed);
if (keys.length > 5000) {
  keys.sort((a, b) => sd.processed[a].localeCompare(sd.processed[b]));
  for (const k of keys.slice(0, keys.length - 5000)) delete sd.processed[k];
}
// The lock item goes first so the Take lock branch runs before Whisper starts.
if (voiceTaken > 0) out.unshift({ json: { target: 'lock' } });
return out;

// Normalises a webhook upload to the same item shape the folder scan produces.
// POST /webhook/inbox-upload-0001/inbox/<target>, multipart: one file in any field, plus optional
// `notebook` (bujo) and `source`.
const TARGETS = ['bujo', 'voice'];
const target = String(($json.params && $json.params.target) || '').toLowerCase();
if (!TARGETS.includes(target)) {
  throw new Error(`Unknown inbox target "${target}". Known: ${TARGETS.join(', ')}`);
}
const body = $json.body || {};
const binaries = $input.item.binary || {};
const field = Object.keys(binaries)[0];
if (!field) throw new Error('No file in the upload');
const bin = binaries[field];
const name = bin.fileName || 'upload';
return {
  json: {
    key: null,
    target,
    notebook: target === 'bujo' ? String(body.notebook || 'Unsorted') : null,
    src: name,
    noteName: name.replace(/\.[^.]+$/, '').replace(/[\\/:*?"<>|]/g, '-'),
    source: String(body.source || 'upload'),
  },
  binary: { data: bin },
};

// The m4a's movie header (mvhd) creation time, seconds since 1904-01-01 UTC. Voice Memos
// re-encodes on Share, so this is when the memo was shared, not recorded (measured 2026-10-15).
// Null when the file has none or it is implausible; Build note then falls back to now. The binary passes through to Whisper.
const MAC_EPOCH = Date.UTC(1904, 0, 1);
const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  let recordedAt = null;
  try {
    const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
    const at = buf.indexOf('mvhd');
    if (at >= 4) {
      const secs = buf[at + 4] === 1 ? Number(buf.readBigUInt64BE(at + 8)) : buf.readUInt32BE(at + 8);
      const ms = MAC_EPOCH + secs * 1000;
      if (ms > Date.UTC(2000, 0, 1) && ms < Date.now() + 86400000) recordedAt = new Date(ms).toISOString();
    }
  } catch (e) {
    // Unreadable or not an MP4 container: fall back to the time of transcription.
  }
  out.push({ json: { ...items[i].json, recordedAt }, binary: items[i].binary, pairedItem: { item: i } });
}
return out;

// A recording named with a leading date ("1013 汐止國泰", "20261013 2230 standup",
// "2026-10-13 standup") is dated by its name: Voice Memos re-encodes on Share, so the
// file's own timestamp is when it was shared, not recorded. Returns the date parts and
// the rest of the name; a name without a valid leading date comes back unchanged.
const nameDate = (name) => {
  const m = name.match(/^(?:(\d{4})-?)?(\d{2})-?(\d{2})(?:[ _T-]?(\d{2}):?(\d{2}))?[ _-]+(.+)$/);
  if (!m) return { rest: name };
  const [, y, mo, d, h, mi, rest] = m;
  const month = +mo, day = +d;
  if (month < 1 || month > 12 || day < 1 || day > 31) return { rest: name };
  if (h !== undefined && (+h > 23 || +mi > 59)) return { rest: name };
  return { year: y ? +y : null, month, day, hour: h === undefined ? null : +h, minute: h === undefined ? null : +mi, rest };
};

const routed = $('Route').item.json;
const sharedAt = $('Recorded at').item.json.recordedAt;
const text = ($json.text || '').trim();
const now = $now.setZone('Asia/Taipei');
// The file's mvhd time is when it was shared, the best guess when the name carries no date.
const shared = sharedAt ? DateTime.fromISO(sharedAt).setZone('Asia/Taipei') : null;
const base = shared || now;
const fromName = nameDate(routed.noteName);
let at = base;
let stamp = 'yyyy-MM-dd HHmm';
let title = routed.noteName;
if (fromName.month) {
  let d = DateTime.fromObject(
    { year: fromName.year || base.year, month: fromName.month, day: fromName.day, hour: fromName.hour || 0, minute: fromName.minute || 0 },
    { zone: 'Asia/Taipei' },
  );
  // A bare MMDD later than the share date belongs to last year (recorded in December, shared in January).
  if (d.isValid && !fromName.year && d > base.plus({ days: 1 })) d = d.minus({ years: 1 });
  if (d.isValid) {
    at = d;
    stamp = fromName.hour === null ? 'yyyy-MM-dd' : 'yyyy-MM-dd HHmm';
    title = fromName.rest;
  }
}
const body = [
  '---',
  'type: voice-memo',
  `source: ${routed.src}`,
  `date: ${at.toFormat('yyyy-MM-dd')}`,
  ...(shared ? [`shared: ${shared.toISO({ suppressMilliseconds: true })}`] : []),
  `transcribed: ${now.toISO({ suppressMilliseconds: true })}`,
  '---',
  '',
  text || '_(empty transcription)_',
  '',
].join('\n');
// Named by date so notes sort by time: the name's own date when it has one, else the share time.
return { json: { noteName: `${at.toFormat(stamp)} ${title}`, body } };

// Records a delivered folder file in the ledger; uploads carry no key.
const routed = $('Route').item.json;
const sd = $getWorkflowStaticData('global');
if (routed.key) {
  sd.processed = sd.processed || {};
  sd.processed[routed.key] = new Date().toISOString();
  if (sd.attempts) delete sd.attempts[routed.key];
}
return { json: { ok: true, target: routed.target, src: routed.src, result: $json } };
